class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """

    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            if word:  # skip empty strings at index 0 and 1
                self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {
            'first': 1, 'second': 2, 'third': 3, 'fourth': 4, 'fifth': 5, 'sixth': 6,
            'seventh': 7, 'eighth': 8, 'ninth': 9, 'tenth': 10, 'eleventh': 11,
            'twelfth': 12, 'thirteenth': 13, 'fourteenth': 14, 'fifteenth': 15,
            'sixteenth': 16, 'seventeenth': 17, 'eighteenth': 18, 'nineteenth': 19,
            'twentieth': 20, 'thirtieth': 30, 'fortieth': 40, 'fiftieth': 50,
            'sixtieth': 60, 'seventieth': 70, 'eightieth': 80, 'ninetieth': 90,
            'hundredth': 100, 'thousandth': 1000, 'millionth': 1000000,
            'billionth': 1000000000, 'trillionth': 1000000000000,
        }
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if not textnum or not isinstance(textnum, str):
            raise ValueError("Input must be a non-empty string")

        textnum = textnum.lower().replace('-', ' ')
        current = result = 0
        last_scale = 1
        tokens = textnum.strip().split()
        if not tokens:
            raise ValueError("Input must contain words")

        def parse_ordinal(word):
            if word in self.ordinal_words:
                return self.ordinal_words[word]
            for ending, replacement in self.ordinal_endings:
                if word.endswith(ending):
                    base = word[:-len(ending)] + replacement
                    if base in self.tens:
                        return self.tens.index(base) * 10
                    if base in self.units:
                        return self.units.index(base)
            return None

        for word in tokens:
            if word == 'and':
                # 'and' is ignored in number parsing
                continue

            # Check if word is ordinal word
            val = parse_ordinal(word)
            if val is not None:
                current += val
                continue

            if word not in self.numwords:
                raise ValueError(f"Invalid word found: {word}")

            scale, increment = self.numwords[word]

            if scale > 1:
                if current == 0:
                    current = 1
                current = current * scale
                if scale > last_scale:
                    result += current
                    current = 0
                last_scale = scale
            else:
                current += increment

        return str(result + current)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        False
        """
        if not textnum or not isinstance(textnum, str):
            return False

        textnum = textnum.lower()
        # We do NOT replace hyphens here because example shows "thirty-two" is invalid
        tokens = textnum.strip().split()
        if not tokens:
            return False

        valid_words = set(self.numwords.keys()) | set(self.ordinal_words.keys()) | {'and'}

        for word in tokens:
            if word not in valid_words:
                return False
        return True
